using System.Security.Cryptography;using System.Text;using Microsoft.EntityFrameworkCore;using NLog.Extensions.Logging;using OpenFlux.Zen.Server.Data;using OpenFlux.Zen.Server.Models;using OpenFlux.Zen.Server.Services;
var b=WebApplication.CreateBuilder(args);b.Logging.ClearProviders();b.Logging.AddNLog();b.Services.AddDbContext<AppDbContext>(o=>o.UseSqlite($"Data Source={Path.Combine(AppContext.BaseDirectory,"data","openflux.db")}"));b.Services.AddSingleton<TunnelManager>();b.Services.AddHostedService<HostedRestoreService>();var app=b.Build();Directory.CreateDirectory(Path.Combine(AppContext.BaseDirectory,"data"));using(var s=app.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<AppDbContext>();db.Database.EnsureCreated();if(!db.Settings.Any()){db.Settings.Add(new AppSettings{Username=Environment.GetEnvironmentVariable("OPENFLUX_ADMIN_USER")??"admin",PasswordHash=Hash(Environment.GetEnvironmentVariable("OPENFLUX_ADMIN_PASSWORD")??"change-me"),SecretPath=Convert.ToHexString(RandomNumberGenerator.GetBytes(18)).ToLowerInvariant()});db.SaveChanges();}}app.Use(async(c,n)=>{if(c.Request.Path.StartsWithSegments("/api")&&c.Request.Path!="/api/health"){using var s=app.Services.CreateScope();var st=s.ServiceProvider.GetRequiredService<AppDbContext>().Settings.First();var supplied=c.Request.Headers.Authorization.ToString().Replace("Bearer ","");if(string.IsNullOrWhiteSpace(supplied)||Hash(supplied)!=st.PasswordHash){c.Response.StatusCode=401;return;}}await n();});app.MapGet("/api/health",()=>Results.Ok(new{status="ok"}));app.MapGet("/api/settings",async(AppDbContext db)=>Results.Ok(await db.Settings.AsNoTracking().Select(x=>new{x.Username,x.SecretPath,x.PublicBaseUrl,x.BindNetwork,x.AutoStart}).FirstAsync()));app.MapGet("/api/tunnels",async(TunnelManager m)=>Results.Ok(await m.All()));app.MapPost("/api/tunnels",async(Tunnel t,TunnelManager m)=>Results.Ok(await m.Save(t)));app.MapDelete("/api/tunnels/{id:guid}",async(Guid id,TunnelManager m)=>await m.Delete(id)?Results.NoContent():Results.NotFound());app.MapPost("/api/tunnels/{id:guid}/start",async(Guid id,TunnelManager m)=>await m.Start(id)?Results.Ok():Results.NotFound());app.MapPost("/api/tunnels/{id:guid}/stop",async(Guid id,TunnelManager m)=>await m.Stop(id)?Results.Ok():Results.NotFound());app.UseDefaultFiles();app.UseStaticFiles();app.MapFallbackToFile("index.html");app.Run();static string Hash(string s)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s)));

